using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Text.Json;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Threading;
namespace WorldTime;
public static class City033Tests {
 public static void Ui(string[] args){
  string dir=args[Array.IndexOf(args,"--data-dir")+1];var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var host=new Host(new Store(dir),true,false);var picker=new CityPicker(host,null);picker.Title="WorldTime 0.3.3 · Offline city search";picker.ShowInTaskbar=true;
  if(args.Contains("--report")){string report=args[Array.IndexOf(args,"--report")+1];picker.Loaded+=async(_,_)=>{double shown=(DateTime.UtcNow-Process.GetCurrentProcess().StartTime.ToUniversalTime()).TotalMilliseconds;await picker.Search.RefreshAsync();using var process=Process.GetCurrentProcess();process.Refresh();File.WriteAllText(report,JsonSerializer.Serialize(new{WindowLoadedSinceProcessStartMs=shown,FirstResultsSinceProcessStartMs=(DateTime.UtcNow-process.StartTime.ToUniversalTime()).TotalMilliseconds,PrivateBytes=process.PrivateMemorySize64,process.HandleCount,RowsLoaded=host.S.Rows.Count,Places=picker.CityList.Items.Count,Note="Actual WPF test launcher with loaded independent profile, process/OS caches not cleared; not normal native desktop startup"},new JsonSerializerOptions{WriteIndented=true}));};}
  picker.Closed+=(_,_)=>host.Quit();picker.Show();app.Run();
 }
 public static void Run(string[] args){
  string report=Path.GetFullPath(args[Array.IndexOf(args,"--report")+1]),dir=Path.Combine(Path.GetDirectoryName(report)!,"synthetic-033");Directory.CreateDirectory(dir);var log=new List<string>();int count=0;Host? host=null;var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};
  void Check(bool yes,string name){if(!yes)throw new Exception("FAIL "+name);count++;log.Add("PASS "+name);}
  app.Dispatcher.BeginInvoke(DispatcherPriority.ApplicationIdle,new Action(async()=>{try{
   var process=Process.GetCurrentProcess();long before=process.PrivateMemorySize64;var cold=Stopwatch.StartNew();await Places033.WarmAsync();cold.Stop();process.Refresh();long after=process.PrivateMemorySize64;
   var all=Places033.All;Check(all.Length>30000,"Large offline city catalog");Check(all.Select(c=>c.Id).Distinct().Count()==all.Length,"Stable IDs are unique");Check(all.All(c=>c.Id.StartsWith("geonames:")&&c.Iana.Length>0),"All places retain source ID and IANA");
   var unavailable=all.Where(c=>c.Zone.Length==0).ToArray();File.WriteAllText(Path.Combine(Path.GetDirectoryName(report)!,"unresolved-timezones.json"),JsonSerializer.Serialize(unavailable.Select(c=>new{c.Id,c.En,c.Code,c.Iana}),new JsonSerializerOptions{WriteIndented=true}));
   foreach(var (query,id) in new[]{("旧","5391959"),("旧金","5391959"),("旧金山","5391959"),("San F","5391959"),("Francisco","5391959"),("SF","5391959"),("jiujinshan","5391959"),("bei","1816670"),("bj","1816670"),("beijing","1816670"),("sh","1796236"),("gz","1809858"),("Tokyo","1850147"),("東京","1850147"),("东京","1850147"),("São Paulo","3448439"),("Sao Paulo","3448439"),("샌프란시스코","5391959"),("سان فرانسيسكو","5391959"),("Сан-Франциско","5391959")})Check(Places033.Search(query).Any(c=>c.Id=="geonames:"+id),"Partial/multilingual/alias/pinyin "+query);
   Check(Places033.Search("San Francisco")[0].Id=="geonames:5391959","Exact canonical match first");Check(Places033.Search("Paris").Any(c=>c.Code=="FR")&&Places033.Search("Paris").Any(c=>c.Code=="US"),"Paris identities remain separate");
   Check(Places033.Search("Springfield").Select(c=>c.AdminCode).Distinct().Count()>3,"Springfield states remain distinct");Check(Places033.Search("San Jose").Select(c=>c.Code).Distinct().Count()>1,"San Jose countries remain distinct");Check(Places033.Search("qqqq城市不存在zzzz").Length==0,"No invented places");Check(Places033.Search("S").Length>1000,"Broad search is not truncated");Check(Places033.Search("San","US").All(c=>c.Code=="US"),"Optional country intersects search");
   foreach(var (id,iana,jan,jul) in new[]{("5391959","America/Los_Angeles",-8d,-7d),("5128581","America/New_York",-5d,-4d),("2643743","Europe/London",0d,1d),("2988507","Europe/Paris",1d,2d),("1816670","Asia/Shanghai",8d,8d),("1850147","Asia/Tokyo",9d,9d),("1283240","Asia/Kathmandu",5.75d,5.75d),("2078025","Australia/Adelaide",10.5d,9.5d),("2193733","Pacific/Auckland",13d,12d)}){
    var c=Places033.Find("geonames:"+id)!;Check(c.Iana==iana&&c.Zone.Length>0,"Place-to-zone identity "+c.En);Check(Catalog.Local(c.Zone,DateTimeOffset.Parse("2026-01-15T12:00Z")).Offset.TotalHours==jan&&Catalog.Local(c.Zone,DateTimeOffset.Parse("2026-07-15T12:00Z")).Offset.TotalHours==jul,"Winter/summer fractional/DST "+c.En);
   }
   Check(Places033.Search("圣弗朗西斯科").Any(c=>c.Id=="geonames:5391959"),"Sourced curated San Francisco Chinese alias");Check(Places033.Search("とうきょう").Any(c=>c.Id=="geonames:1850147"),"Sourced Tokyo kana reading");
   var durations=new List<double>();string[] queries={"S","Sa","San","San F","Francisco","旧","旧金","旧金山","SF","bj","bei","jiujinshan","Tokyo","東京","Sao Paulo","Paris","qqqq城市不存在zzzz","سان فرانسيسكو"};
   for(int i=0;i<10;i++)foreach(var q in queries){var watch=Stopwatch.StartNew();Places033.Search(q);durations.Add(watch.Elapsed.TotalMilliseconds);}durations.Sort();process.Refresh();
   File.WriteAllText(Path.Combine(Path.GetDirectoryName(report)!,"search-performance.json"),JsonSerializer.Serialize(new{DataCount=all.Length,ColdIndexMs=cold.Elapsed.TotalMilliseconds,PrivateBefore=before,PrivateAfterIndex=after,PrivateAfterQueries=process.PrivateMemorySize64,WarmQueries=durations.Count,P50Ms=durations[durations.Count/2],P95Ms=durations[(int)(durations.Count*.95)],MaxMs=durations.Max(),Unresolved=unavailable.Length,Environment.ProcessorCount,Runtime=Environment.Version.ToString(),OS=Environment.OSVersion.ToString()},new JsonSerializerOptions{WriteIndented=true}));
   // All I/O below uses a new synthetic profile, never the user's configuration.
   using(var seed=new Store(dir)){seed.Save(new State{Language="zh-Hans",AppearanceVersion=2,Rows=new(){new Row{Id="legacy",City="纽约",Zone="Eastern Standard Time",Code="US",Name="Synthetic friend",Routine=new CityRoutine()}}});}
   host=new Host(new Store(dir),true,false);string old=JsonSerializer.Serialize(host.S.Rows);var picker=new CityPicker(host,null);picker.Show();await picker.Search.RefreshAsync();picker.UpdateLayout();
   Check(picker.CityList.Items.Count==all.Length&&!picker.AddButton.IsEnabled,"All results virtualized, no default auto-selection");Check(VirtualizingPanel.GetIsVirtualizing(picker.CityList),"List virtualization enabled");
   foreach(var query in new[]{"旧","旧金","Francisco","bj","Tokyo","Paris"}){picker.SearchBox.Text=query;await picker.Search.RefreshAsync();Check(picker.CityList.Items.Count==Places033.Search(query).Length,"Real picker has every query result "+query);Check(!picker.AddButton.IsEnabled,"Query refresh clears stale selection "+query);}
   picker.SearchBox.Text="旧金山";await picker.Search.RefreshAsync();picker.CityList.SelectedIndex=Array.FindIndex(picker.CityList.Items.Cast<CitySearchResult>().ToArray(),x=>x.City.Id=="geonames:5391959");Check(picker.AddButton.IsEnabled,"Explicit selection enables add");Check(picker.AddSelected(),"Shared actual picker adds selected San Francisco");var added=host.S.Rows.Single(r=>r.Id!="legacy");Check(added.PlaceId=="geonames:5391959"&&added.Iana=="America/Los_Angeles"&&added.Zone=="Pacific Standard Time","Saved stable place ID and full zone identity");Check(JsonSerializer.Serialize(host.S.Rows.Where(r=>r.Id=="legacy").ToList())==old,"Legacy identity/name/routine/zone unchanged");Check(host.Disk.Load().Rows.Single(r=>r.Id==added.Id).PlaceId==added.PlaceId,"Disk reopen preserves new ID");
   var moment=DateTimeOffset.Parse("2026-07-15T12:00Z");Check(RulerModel.Snapshot(host.S,moment,TimeZoneInfo.Utc).Single(p=>p.Id==added.Id).Local==Catalog.Local(added.Zone,moment),"Shared ruler/ring snapshot uses same selected city time");
   var manual=new CityPicker(host,null);manual.Show();await manual.Search.RefreshAsync();manual.Search.ManualName.Text="Synthetic custom place";manual.ZoneSelector.SelectedItem=TimeZoneInfo.FindSystemTimeZoneById("Nepal Standard Time");Check(manual.Search.MakeSelection() is {PlaceId:"",Zone:"Nepal Standard Time",City:"Synthetic custom place"},"Manual name requires explicit real zone");
   manual.SearchBox.Text="Urumqi";await manual.Search.RefreshAsync();manual.CityList.SelectedIndex=Array.FindIndex(manual.CityList.Items.Cast<CitySearchResult>().ToArray(),c=>c.City.Iana=="Asia/Urumqi");Check(!manual.AddButton.IsEnabled&&manual.Search.CivilZone.Visibility==Visibility.Visible,"Xinjiang time convention requires explicit choice");manual.Search.CivilZone.SelectedIndex=0;Check(manual.Search.MakeSelection() is{Zone:"China Standard Time",Iana:"Asia/Shanghai"},"Explicit China civil time preserves city ID with UTC+8 zone");manual.Search.CivilZone.SelectedIndex=1;Check(manual.Search.MakeSelection() is{Zone:"Central Asia Standard Time",Iana:"Asia/Urumqi"},"Explicit Xinjiang local time uses UTC+6");manual.Close();
   foreach(var lang in new[]{"en","zh-Hans","zh-Hant","ja"}){host.S.Language=lang;var p=new CityPicker(host,null);p.Show();p.SearchBox.Text="东京";await p.Search.RefreshAsync();Check(p.CityList.Items.Cast<CitySearchResult>().Any(r=>r.City.Id=="geonames:1850147"),"Search language independent of UI "+lang);p.Close();}
   host.Manager.Close();
  }catch(Exception e){log.Add(e.ToString());Environment.ExitCode=1;}finally{if(host!=null){host.Exiting=true;host.Ruler?.DisposeMotion();host.Ruler?.Desktop.Dispose();host.Tray.Dispose();host.Disk.Dispose();}log.Add("TOTAL "+count+" PASS; programmatic synthetic WPF, not real IME input acceptance");File.WriteAllLines(report,log);app.Shutdown();}}));app.Run();
 }
}
